import React, { useState } from "react";
import { useNavigate, Link } from "react-router-dom";
import axios from "axios";
import "./Login.css";

function Login() {
  const navigate = useNavigate();
  const [formData, setFormData] = useState({
    email: "",
    password: ""
  });
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState("");

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
    setError("");
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsLoading(true);
    setError("");

    try {
      console.log('🔐 Tentative de connexion vers le backend...');
      
      // Appel API vers votre backend
      const response = await axios.post('http://localhost:5000/api/auth/login', {
        email: formData.email,
        password: formData.password
      });

      console.log('✅ Réponse du backend:', response.data);

      if (response.data.success && response.data.data) {
        const { token, user } = response.data.data;
        
        // Sauvegarder les vraies données de la BD
        localStorage.setItem('token', token);
        localStorage.setItem('user', JSON.stringify(user));
        localStorage.setItem('isAuthenticated', 'true');
        localStorage.setItem('userRole', user.role);

        console.log('👤 Données utilisateur depuis la BD:', user);
        
        alert(`✅ Connexion réussie! Bienvenue ${user.nom}`);
        
        // Redirection selon le rôle
        if (user.role === 'prof') {
          navigate('/dashboard-prof');
        } else if (user.role === 'student') {
          navigate('/dashboard-student');
        } else {
          navigate('/dashboard');
        }
      } else {
        setError(response.data.message || 'Erreur de connexion');
      }

    } catch (err) {
      console.error('💥 Erreur de connexion:', err);
      
      // Messages d'erreur détaillés
      if (err.code === 'NETWORK_ERROR' || err.code === 'ECONNREFUSED') {
        setError('❌ Serveur indisponible. Vérifiez que le backend est démarré sur le port 5000');
      } else if (err.response?.status === 400) {
        setError(err.response.data.message || 'Email ou mot de passe incorrect');
      } else if (err.response?.status === 500) {
        setError('❌ Erreur serveur. Vérifiez la console du backend');
      } else {
        setError('Erreur de connexion au serveur');
      }
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="login-container">
      <div className="login-card">
        <div className="login-header">
          <div className="logo">
            <i className="fas fa-graduation-cap"></i>
            <span>Gestion Cours</span>
          </div>
          <h2>Connexion</h2>
          <p>Connectez-vous à votre compte</p>
        </div>

        {error && (
          <div className="error-message">
            <i className="fas fa-exclamation-circle"></i>
            {error}
          </div>
        )}

        <form onSubmit={handleSubmit} className="login-form">
          <div className="form-group">
            <label htmlFor="email">Email</label>
            <input
              type="email"
              id="email"
              name="email"
              value={formData.email}
              onChange={handleChange}
              required
              placeholder="votre@email.com"
              disabled={isLoading}
            />
          </div>

          <div className="form-group">
            <label htmlFor="password">Mot de passe</label>
            <input
              type="password"
              id="password"
              name="password"
              value={formData.password}
              onChange={handleChange}
              required
              placeholder="Votre mot de passe"
              disabled={isLoading}
            />
          </div>
           <p>
   se connecter ? <Link to="/zz">Créer un compte</Link>
 </p>

        </form>

        <div className="login-footer">
          <p>
            Pas de compte ? <Link to="/register">Créer un compte</Link>
          </p>
        </div>
      </div>
    </div>
  );
}

export default Login;
